ST.xhtml:p:
nFilterTime :=LREAL_TO_TIME(FUN_MSTOS(nFilterTime_Limit));
FOR Index := 0 TO 3 BY 1 DO
	CASE Index Of
		0:
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0] := g_biDualAxis1PosLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1] := g_biDualAxis1NegLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[2] := g_biDualAxis1ZeroSignal;
		1:
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0] := g_biDualAxis2PosLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1] := g_biDualAxis2NegLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[2] := g_biDualAxis2ZeroSignal;
		2:
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0] := g_biDualAxis3PosLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1] := g_biDualAxis3NegLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[2] := g_biDualAxis3ZeroSignal;
		3:
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0] := g_biDualAxis4PosLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1] := g_biDualAxis4NegLimit;
			g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[2] := g_biDualAxis4ZeroSignal;
	END_CASE;

  (*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位*)
	IF g_NCMoveData.NCAXISDATA[Index].AxisHomeSignal = 0 THEN
		g_NCMoveData.NCAXISDATA[Index].AxisZero := FUN_SingalLogic(g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[2],g_NCMoveData.NCAXISDATA[Index].AxisZeroSignalLogic);
	ELSIF g_NCMoveData.NCAXISDATA[Index].AxisHomeSignal = 1 THEN
		g_NCMoveData.NCAXISDATA[Index].AxisZero := FUN_SingalLogic(g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0],g_NCMoveData.NCAXISDATA[Index].AxisPosLimitLogic);
	ELSE
		g_NCMoveData.NCAXISDATA[Index].AxisZero := FUN_SingalLogic(g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1],g_NCMoveData.NCAXISDATA[Index].AxisNegLimitLogic);
	END_IF;
  Filter_PosLimit[Index](nFilterTime,g_NCMoveData.NCAXISDATA[Index].AxisPosLimitLogic,g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[0] ,g_NCMoveData.NCAXISDATA[Index].Filter_PosLimit); 
  Filter_NegLimit[Index](nFilterTime,g_NCMoveData.NCAXISDATA[Index].AxisNegLimitLogic,g_NCMoveData.NCAXISDATA[Index].AxisSignalArr[1],g_NCMoveData.NCAXISDATA[Index].Filter_NegLimit);

  g_NCMoveData.NCAXISDATA[Index].AxisPosLimit := FUN_SingalLogic(g_NCMoveData.NCAXISDATA[Index].Filter_PosLimit ,g_NCMoveData.NCAXISDATA[Index].AxisPosLimitLogic);
  g_NCMoveData.NCAXISDATA[Index].AxisNegLimit := FUN_SingalLogic(g_NCMoveData.NCAXISDATA[Index].Filter_NegLimit ,g_NCMoveData.NCAXISDATA[Index].AxisNegLimitLogic);
END_FOR;
